import { readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { build } from "esbuild";

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "..");
const bundleRelativePath = "root-site/shell/shell.bundle.js";
const bundlePath = join(repoRoot, bundleRelativePath);
const args = process.argv.slice(2);
const checkOnly = args.includes("--check");
const unknownArgs = args.filter((arg) => arg !== "--check");

if (unknownArgs.length) {
  throw new Error(`Unknown shell bundle option: ${unknownArgs.join(", ")}`);
}

const result = await build({
  absWorkingDir: repoRoot,
  entryPoints: ["root-site/shell/shell.js"],
  outfile: bundleRelativePath,
  bundle: true,
  format: "iife",
  platform: "browser",
  charset: "ascii",
  banner: {
    js: "// GENERATED by scripts/build-shell-bundle.mjs from root-site/shell/shell.js. DO NOT EDIT."
  },
  logLevel: "silent",
  write: false
});

const output = result.outputFiles.find((file) => file.path === bundlePath) ?? result.outputFiles[0];
if (!output) throw new Error("esbuild did not produce the shell bundle.");

if (checkOnly) {
  const current = await readFile(bundlePath).catch(() => null);
  if (!current || !current.equals(Buffer.from(output.contents))) {
    console.error(`[shell-bundle] ${bundleRelativePath} is stale. Run npm run build:shell.`);
    process.exitCode = 1;
  } else {
    console.log(`[shell-bundle] ${bundleRelativePath} matches shell.js`);
  }
} else {
  await writeFile(bundlePath, output.contents);
  console.log(`[shell-bundle] generated ${bundleRelativePath}`);
}
